import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { DISPATCH_CREATION_DEFAULTS } from "@/lib/dispatch/admin-presentation";
import { DRIVER_SETUP_INCOMPLETE_MESSAGE, DRIVER_SETUP_LABELS, driverSetupChoiceForClassification } from "@/lib/dispatch/driver-setup";
import { listDispatchDrivers } from "@/lib/dispatch/drivers";
import { SUPPLY_CLASSIFICATIONS, SUPPLY_CLASSIFICATION_LABELS, driverSupplyRelationshipLabel, supplyClassificationLabel, supplyClassificationPresentation, supplyRelationshipReview, vehicleControlRelationshipLabel } from "@/lib/dispatch/supply-classification";
import { getDispatchVendor, listDispatchVendors } from "@/lib/dispatch/vendors";
import { listDispatchVehicles } from "@/lib/dispatch/vehicles";
import { NORMAL_RENTAL_ZONES } from "@/lib/normal-rental/zones";
import { hasAdminSession } from "../_lib/session";
import DispatchAdminNav from "../_components/DispatchAdminNav";
import { Active, input, label, priorityOptions, Select, textarea, Zones } from "../_components/DispatchFormFields";
import { completeDriverSetup, saveVendor } from "./actions";

export const metadata: Metadata = { title: "Dispatch Vendors | RentKA Admin", robots: { index: false, follow: false, noarchive: true, nosnippet: true } };
const badge = (active: boolean) => active ? "bg-green-100 text-green-800" : "bg-slate-200 text-slate-700";

export default async function Page({ searchParams }: { searchParams: Promise<Record<string, string | undefined>> }) {
  if (!(await hasAdminSession())) redirect("/admin/pricing-calculator");
  const q = await searchParams;
  const [all, vehicles, drivers, editing] = await Promise.all([listDispatchVendors(), listDispatchVehicles(), listDispatchDrivers(), q.edit ? getDispatchVendor(q.edit) : null]);
  const rows = all.filter((vendor) => (!q.search || `${vendor.name} ${vendor.contactName ?? ""} ${vendor.primaryPhone}`.toLowerCase().includes(q.search.toLowerCase())) && (!q.zone || vendor.zoneIds.includes(q.zone as never)) && (!q.state || (q.state === "active" ? vendor.active : !vendor.active)) && (!q.classification || vendor.supplyClassification === q.classification));
  const editingAllDrivers = editing ? drivers.filter((driver) => driver.vendorId === editing.id) : [];
  const editingVehicles = editing ? vehicles.filter((vehicle) => vehicle.vendorId === editing.id) : [];
  const editingDrivers = editingAllDrivers.filter((driver) => driver.supplyRelationship === "independent_owner_driver");
  const selectedClassification = editing?.supplyClassification ?? DISPATCH_CREATION_DEFAULTS.vendor.supplyClassification;
  const editingReview = editing ? supplyRelationshipReview(editing.supplyClassification, editingAllDrivers, editingVehicles) : null;
  const editingDriverChoice = editing ? driverSetupChoiceForClassification(editing.supplyClassification) : undefined;
  const editingDriverSetupComplete = (editingDriverChoice === "vendor_driver" && editingAllDrivers.some((driver) => driver.active && driver.status === "available" && driver.supplyRelationship === "vendor_managed")) || (editingDriverChoice === "self" && editingAllDrivers.some((driver) => driver.id === editing?.independentOwnerDriverId && driver.supplyRelationship === "independent_owner_driver"));
  return <main className="min-h-screen bg-slate-100 p-4 md:p-8"><div className="mx-auto max-w-7xl">
    <DispatchAdminNav current="vendors" />
    <header className="mb-6"><p className="text-sm font-bold uppercase tracking-widest text-[#5BAE4A]">Dispatch operations</p><h1 className="text-3xl font-black text-[#0F2B46]">Vendors</h1><p className="text-slate-600">Set up each owner or fleet and choose who will drive their vehicles.</p></header>
    {q.error && <p role="alert" className="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800">{q.error}</p>}{q.saved && <p className="mb-4 rounded-lg bg-green-50 p-3 text-sm text-green-800">{q.saved}</p>}
    <section className="mb-6 rounded-2xl bg-white p-5 shadow-sm"><h2 className="text-xl font-black text-[#0F2B46]">{editing ? "Edit vendor" : "Add vendor"}</h2><form action={saveVendor} className="mt-4 grid gap-4 md:grid-cols-2">
      <input type="hidden" name="id" value={editing?.id ?? ""} />
      <label className={label}>Vendor/company name<input className={input} name="name" required maxLength={160} defaultValue={editing?.name} /></label>
      <label className={label}>Primary contact name<input className={input} name="contactName" maxLength={120} defaultValue={editing?.contactName} /></label>
      <label className={label}>Primary phone<input className={input} name="primaryPhone" required maxLength={40} placeholder="03020589999" defaultValue={editing?.primaryPhone} /></label>
      <label className={label}>Operational WhatsApp<input className={input} name="whatsappNumber" required maxLength={40} placeholder="923020589999" defaultValue={editing?.whatsappNumber} /></label>
      <Zones selected={editing?.zoneIds} />
      <label className={label}>Priority<Select name="priority" value={editing?.priority ?? DISPATCH_CREATION_DEFAULTS.vendor.priority} options={priorityOptions} /></label>
      <details className="md:col-span-2 rounded-xl border p-4"><summary className="cursor-pointer font-black text-[#0F2B46]">Advanced internal routing</summary><div className="mt-4 grid gap-4 md:grid-cols-2"><label className={label}>Driving arrangement<Select name="supplyClassification" value={selectedClassification} options={SUPPLY_CLASSIFICATIONS} labels={SUPPLY_CLASSIFICATION_LABELS} /></label>{editing && <label className={label}>Owner profile used for driving<select className={input} name="independentOwnerDriverId" defaultValue={editing.independentOwnerDriverId ?? ""}><option value="">Not set up</option>{editingDrivers.map((driver) => <option key={driver.id} value={driver.id}>{driver.name}</option>)}</select></label>}</div></details>
      <p className="rounded-lg bg-amber-50 p-3 text-sm font-bold text-amber-900 md:col-span-2">{supplyClassificationPresentation(selectedClassification)}</p>
      <details className="md:col-span-2 rounded-xl border p-4"><summary className="cursor-pointer font-black text-[#0F2B46]">Optional existing-record references</summary><div className="mt-4 grid gap-4 md:grid-cols-2"><label className={label}>Legacy public vendor ID<input className={input} name="legacyVendorId" defaultValue={editing?.legacyVendorId} /></label><label className={label}>Normal rental vendor ID<input className={input} name="normalRentalVendorId" defaultValue={editing?.normalRentalVendorId} /></label></div></details>
      <label className={`${label} md:col-span-2`}>Internal notes<textarea className={textarea} name="notes" defaultValue={editing?.notes} /></label><Active value={editing?.active ?? DISPATCH_CREATION_DEFAULTS.vendor.active} />
      <div className="flex gap-2"><button className="rounded-lg bg-[#0F2B46] px-5 py-2.5 font-bold text-white">Save vendor</button>{editing && <Link href="/admin/vendors" className="rounded-lg border px-5 py-2.5">Cancel</Link>}</div>
    </form></section>
    {editing && <section id="driver-setup" className={`mb-6 scroll-mt-24 rounded-2xl border-2 bg-white p-5 shadow-sm ${editingDriverSetupComplete ? "border-green-300" : "border-amber-400"}`}><h2 className="text-xl font-black text-[#0F2B46]">{editing.name}</h2><p className="mt-1 font-bold">{editingDriverSetupComplete ? "Driver setup complete" : "Driver setup incomplete"}</p>{!editingDriverSetupComplete && <p className="mt-1 text-sm text-amber-900">{DRIVER_SETUP_INCOMPLETE_MESSAGE}</p>}<form action={completeDriverSetup} className="mt-4 grid gap-4"><input type="hidden" name="id" value={editing.id}/><fieldset><legend className="text-lg font-black text-[#0F2B46]">Who will drive this vehicle?</legend><div className="mt-3 grid gap-3 sm:grid-cols-2"><label className="rounded-xl border p-4 font-bold"><input type="radio" name="driverSetupChoice" value="self" required defaultChecked={editingDriverChoice === "self"}/> {DRIVER_SETUP_LABELS.self}</label><label className="rounded-xl border p-4 font-bold"><input type="radio" name="driverSetupChoice" value="vendor_driver" required defaultChecked={editingDriverChoice === "vendor_driver"}/> {DRIVER_SETUP_LABELS.vendor_driver}</label></div></fieldset><label className={label}>Choose a vendor driver <span className="font-normal text-slate-500">(only when one of the vendor&apos;s drivers will drive)</span><select className={input} name="driverId" defaultValue=""><option value="">Select an active vendor driver</option>{editingAllDrivers.filter((driver) => driver.active && driver.status === "available").map((driver) => <option key={driver.id} value={driver.id}>{driver.name}</option>)}</select></label><p className="text-sm text-slate-600">Choosing self-drive uses the owner profile automatically. This setup does not assign a booking or send any message.</p><button className="w-fit rounded-lg bg-[#0F2B46] px-5 py-2.5 font-bold text-white">Save Driver Setup</button></form></section>}
    {editing && editingReview && <section className="mb-6 rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-bold uppercase tracking-wide text-slate-500">Supply account</p><h2 className="text-2xl font-black text-[#0F2B46]">{editing.name}</h2><p className="mt-1 text-sm">Operational WhatsApp: <strong>{editing.whatsappNumber}</strong></p><p className="mt-1 text-sm">Zones: {editing.zoneIds.map((zone) => NORMAL_RENTAL_ZONES[zone].label).join(" · ")}</p></div><span className={`rounded-full px-3 py-2 text-sm font-black ${editingReview.needsReview ? "bg-red-100 text-red-800" : "bg-green-100 text-green-800"}`}>{editingReview.needsReview ? "NEEDS REVIEW" : "RELATIONSHIPS VALID"}</span></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div className="rounded-xl border p-4"><div className="flex items-center justify-between"><h3 className="font-black text-[#0F2B46]">Drivers: {editingAllDrivers.length}</h3><div className="flex gap-2"><Link className="text-sm font-bold underline" href={`/admin/drivers?vendor=${editing.id}`}>View Drivers</Link><Link className="text-sm font-bold underline" href={`/admin/drivers?vendor=${editing.id}#add-driver`}>Add Driver</Link></div></div><ul className="mt-3 space-y-2 text-sm">{editingAllDrivers.map((driver) => <li key={driver.id} className="flex justify-between gap-3"><span>{driver.name}</span><span className={driver.supplyRelationship === "unknown_needs_review" ? "font-bold text-red-700" : "text-slate-500"}>{driverSupplyRelationshipLabel(driver.supplyRelationship)}</span></li>)}{!editingAllDrivers.length && <li className="text-slate-500">No drivers linked.</li>}</ul></div><div className="rounded-xl border p-4"><div className="flex items-center justify-between"><h3 className="font-black text-[#0F2B46]">Vehicles: {editingVehicles.length}</h3><div className="flex gap-2"><Link className="text-sm font-bold underline" href={`/admin/vehicles?vendor=${editing.id}`}>View Vehicles</Link><Link className="text-sm font-bold underline" href={`/admin/vehicles?vendor=${editing.id}#add-vehicle`}>Add Vehicle</Link></div></div><ul className="mt-3 space-y-2 text-sm">{editingVehicles.map((vehicle) => <li key={vehicle.id} className="flex justify-between gap-3"><span>{vehicle.make} {vehicle.model} · {vehicle.registrationNumber}</span><span className={vehicle.controlRelationship === "unknown_needs_review" ? "font-bold text-red-700" : "text-slate-500"}>{vehicleControlRelationshipLabel(vehicle.controlRelationship)}</span></li>)}{!editingVehicles.length && <li className="text-slate-500">No vehicles linked.</li>}</ul></div></div>{editingReview.contradictions > 0 && <p className="mt-4 rounded-lg bg-red-50 p-3 text-sm font-bold text-red-800">{editingReview.contradictions} relationship contradiction(s) must be resolved before changing this supply classification.</p>}</section>}
    <form className="mb-4 grid gap-2 rounded-xl bg-white p-3 sm:grid-cols-2 lg:grid-cols-5"><input className={input} name="search" placeholder="Search name or phone" defaultValue={q.search} /><select className={input} name="zone" defaultValue={q.zone ?? ""}><option value="">All zones</option>{Object.entries(NORMAL_RENTAL_ZONES).map(([id, zone]) => <option key={id} value={id}>{zone.label}</option>)}</select><select className={input} name="state" defaultValue={q.state ?? ""}><option value="">All states</option><option value="active">Active</option><option value="inactive">Inactive</option></select><select className={input} name="classification" defaultValue={q.classification ?? ""}><option value="">All classifications</option>{SUPPLY_CLASSIFICATIONS.map((value) => <option key={value} value={value}>{SUPPLY_CLASSIFICATION_LABELS[value]}</option>)}</select><button className="rounded-lg bg-slate-800 px-4 py-2 text-white">Filter</button></form>
    <div className="mb-4"><Link href="/admin/vendors?classification=unknown_needs_review" className="inline-flex rounded-lg border border-amber-400 bg-amber-50 px-4 py-2 text-sm font-black text-amber-900">Driver Setup Needs Attention</Link></div>
    <section className="grid gap-4">{rows.map((vendor) => { const vendorVehicles = vehicles.filter((vehicle) => vehicle.vendorId === vendor.id), vendorDrivers = drivers.filter((driver) => driver.vendorId === vendor.id), review = supplyRelationshipReview(vendor.supplyClassification, vendorDrivers, vendorVehicles), driverChoice = driverSetupChoiceForClassification(vendor.supplyClassification), driverSetupComplete = (driverChoice === "vendor_driver" && vendorDrivers.some((driver) => driver.active && driver.status === "available" && driver.supplyRelationship === "vendor_managed")) || (driverChoice === "self" && vendorDrivers.some((driver) => driver.id === vendor.independentOwnerDriverId && driver.supplyRelationship === "independent_owner_driver")); return <article key={vendor.id} className={`rounded-2xl bg-white p-5 shadow-sm ${review.needsReview ? "border-2 border-amber-400" : ""}`}><div className="flex flex-wrap justify-between gap-3"><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-lg font-black text-[#0F2B46]">{vendor.name}</h2><span className={`rounded-full px-2 py-1 text-xs font-bold ${badge(vendor.active)}`}>{vendor.active ? "Active" : "Inactive"}</span><span className="rounded-full bg-blue-50 px-2 py-1 text-xs">{vendor.priority}</span><span className={`rounded-full px-2 py-1 text-xs font-black ${vendor.supplyClassification === "unknown_needs_review" ? "bg-red-100 text-red-800" : "bg-amber-50 text-amber-900"}`}>{supplyClassificationLabel(vendor.supplyClassification)}</span>{review.needsReview && <span className="rounded-full bg-red-100 px-2 py-1 text-xs font-black text-red-800">NEEDS REVIEW</span>}</div><p className="mt-1 text-sm">{vendor.contactName || "No contact name"} · {vendor.primaryPhone} · WhatsApp {vendor.whatsappNumber}</p><p className="mt-1 text-xs text-slate-500">{vendor.zoneIds.map((zone) => NORMAL_RENTAL_ZONES[zone].label).join(" · ")}</p>{!driverSetupComplete && <p className="mt-2 rounded-lg bg-amber-50 p-3 text-sm font-bold text-amber-900">{DRIVER_SETUP_INCOMPLETE_MESSAGE}</p>}<p className="mt-2 text-sm font-bold text-[#0F2B46]">{supplyClassificationPresentation(vendor.supplyClassification)}</p>{(vendor.onboardingApplicationId || vendor.legacyVendorId) && <p className="mt-1 text-xs text-slate-500">{vendor.onboardingApplicationId ? `Onboarding ${vendor.onboardingApplicationId}` : ""}{vendor.legacyVendorId ? ` · Legacy ${vendor.legacyVendorId}` : ""}</p>}</div><Link href={`/admin/vendors?edit=${vendor.id}#driver-setup`} className="h-fit rounded-lg border px-4 py-2 text-sm font-bold">{driverSetupComplete ? "Manage supply account" : "Complete Driver Setup"}</Link></div><div className="mt-4 flex flex-wrap gap-2 text-sm"><Link className="rounded-lg border px-3 py-2 font-bold text-[#0F2B46]" href={`/admin/vehicles?vendor=${vendor.id}`}>View Vehicles ({vendorVehicles.length})</Link><Link className="rounded-lg border px-3 py-2 font-bold text-[#0F2B46]" href={`/admin/drivers?vendor=${vendor.id}`}>View Drivers ({vendorDrivers.length})</Link><Link className="rounded-lg bg-[#0F2B46] px-3 py-2 font-bold text-white" href={`/admin/vehicles?vendor=${vendor.id}#add-vehicle`}>Add Vehicle</Link><Link className="rounded-lg bg-[#0F2B46] px-3 py-2 font-bold text-white" href={`/admin/drivers?vendor=${vendor.id}#add-driver`}>Add Driver</Link></div></article>; })}{!rows.length && <p className="rounded-xl border border-dashed bg-white p-6 text-center text-slate-500">No vendors match these filters.</p>}</section>
  </div></main>;
}
